def is_palindrome(arr):
    return arr == arr[::-1]

def min_changes_to_palindrome(arr):
    if len(arr) <= 1:
        return 0

    if is_palindrome(arr):
        return 0

    changes = 0
    left, right = 0, len(arr) - 1

    while left < right:
        if arr[left] != arr[right]:
            changes += 1
        left += 1
        right -= 1

    return changes

